import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetInventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("INVENTORY_DB_URL");
    private static final String DB_USER = System.getenv("INVENTORY_DB_USER");
    private static final String DB_PASS = System.getenv("INVENTORY_DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String location = req.getParameter("location");
        String sortCol = req.getParameter("sort");

        if (assetType == null || assetType.isEmpty()) {
            resp.sendError(400, "Missing required parameter: type");
            return;
        }

        // Validate assetType against known enum values
        if (!isValidAssetType(assetType)) {
            resp.sendError(400, "Invalid asset type");
            return;
        }

        // Build query - sort column is user-controlled
        StringBuilder query = new StringBuilder();
        query.append("SELECT asset_id, asset_name, asset_type, location, status ");
        query.append("FROM inventory WHERE asset_type = ?");

        if (location != null && !location.isEmpty()) {
            query.append(" AND location = ?");
        }

        // Sort column injection point - no parameterization possible for ORDER BY
        if (sortCol != null && !sortCol.isEmpty()) {
            query.append(" ORDER BY ").append(sortCol);
        } else {
            query.append(" ORDER BY asset_name");
        }

        logger.info("Executing inventory query for type=" + assetType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            stmt.setString(1, assetType);
            if (location != null && !location.isEmpty()) {
                stmt.setString(2, location);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": \"%s\", \"name\": \"%s\", \"type\": \"%s\", \"location\": \"%s\", \"status\": \"%s\"}",
                    rs.getString("asset_id"),
                    rs.getString("asset_name"),
                    rs.getString("asset_type"),
                    rs.getString("location"),
                    rs.getString("status"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    private boolean isValidAssetType(String type) {
        String[] valid = {"server", "workstation", "network", "storage", "peripheral"};
        for (String v : valid) {
            if (v.equalsIgnoreCase(type)) return true;
        }
        return false;
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.sendError(405, "Method not allowed");
    }
}
